47	        jdbc.update("DELETE FROM command_log");
48	        jdbc.update("DELETE FROM approval");
49	        jdbc.update("DELETE FROM recall");
50	        jdbc.update("DELETE FROM test_result");
51	        jdbc.update("DELETE FROM batch_required_test");
52	        jdbc.update("DELETE FROM batch");
53	    }
54	
55	    // ---------- 主流程 ----------
56	
57	    @Test
58	    void happyFlow_quarantineToReleasedThenRecalled() throws Exception {
59	        String batchKey = "BK-HAPPY-" + unique();
60	        createBatch(batchKey, List.of("外观", "含量", "无菌"), 201);
61	
62	        // 初始隔离，出现在可用列表
63	        assertEquals("QUARANTINED", currentStatus(batchKey));
64	        assertTrue(availableKeys().contains(batchKey));
65	
66	        submitTest(batchKey, testReq("TK-1", "外观", "PASS", "inspect-a"), null, null, 201);
67	        assertEquals("QUARANTINED", currentStatus(batchKey));
68	        submitTest(batchKey, testReq("TK-2", "含量", "PASS", "inspect-b"), null, null, 201);
69	        assertEquals("QUARANTINED", currentStatus(batchKey));
70	        submitTest(batchKey, testReq("TK-3", "无菌", "PASS", "inspect-c"), null, null, 201);
71	        assertEquals("PENDING_RELEASE", currentStatus(batchKey));
72	
73	        approve(batchKey, "qa-1", "QUALITY", "CK-AP-1", 201);
74	        assertEquals("RELEASE_REVIEW", currentStatus(batchKey));
75	        approve(batchKey, "ops-1", "OPERATIONS", "CK-AP-2", 201);
76	        assertEquals("RELEASED", currentStatus(batchKey));
77	
78	        // 召回：立即离开可用列表，但历史完整保留
79	        recall(batchKey, "any-user", "客户投诉，疑似污染", "CK-RC-1", 201);
80	        assertEquals("RECALLED", currentStatus(batchKey));
81	        assertFalse(availableKeys().contains(batchKey));
82	
83	        MvcResult historyResult = mockMvc.perform(get("/api/batches/" + batchKey + "/history"))
84	                .andExpect(status().isOk()).andReturn();
85	        JsonNode history = objectMapper.readTree(historyResult.getResponse().getContentAsString());
86	        assertEquals(3, history.path("tests").size());
87	        assertEquals(2, history.path("approvals").size());
88	        assertEquals("RECALLED", history.path("batch").path("status").asText());
89	        assertEquals("客户投诉，疑似污染", history.path("recall").path("reason").asText());
90	        assertEquals("RELEASED", history.path("approvals").get(1).path("batchStatus").asText());
91	    }
92	
93	    // ---------- 失败分支 ----------
94	
95	    @Test
96	    void anyFail_immediatelyRejected_andBlocksTestsApprovalsAndRecall() throws Exception {
97	        String batchKey = "BK-FAIL-" + unique();
98	        createBatch(batchKey, List.of("t1", "t2"), 201);
99	        submitTest(batchKey, testReq("TK-F", "t1", "FAIL", "insp-1"), null, null, 201);
100	        assertEquals("REJECTED", currentStatus(batchKey));
101	
102	        // 已拒绝不能再检验、不能批准、不能召回（召回仅针对 RELEASED）
103	        submitTest(batchKey, testReq("TK-P", "t2", "PASS", "insp-2"), null, null, 409);
104	        approve(batchKey, "qa-9", "QUALITY", "CK-A", 409);
105	        recall(batchKey, "u", "r", "CK-R", 409);
106	        // REJECTED 批次仍在当前列表中（只有召回才从可用列表移除）
107	        assertTrue(availableKeys().contains(batchKey));
108	    }
109	
110	    @Test
111	    void unknownTestItem_returns422() throws Exception {
112	        String batchKey = "BK-BADITEM-" + unique();
113	        createBatch(batchKey, List.of("t1"), 201);
114	        submitTest(batchKey, testReq("TK-X", "不存在的项目", "PASS", "i"), null, null, 422);
115	        assertEquals("QUARANTINED", currentStatus(batchKey));
116	    }
117	
118	    @Test
119	    void approveBeforeAllTestsPassed_returns422() throws Exception {
120	        String batchKey = "BK-EARLY-" + unique();
121	        createBatch(batchKey, List.of("t1", "t2"), 201);
122	        submitTest(batchKey, testReq("TK-1", "t1", "PASS", "insp"), null, null, 201);
123	        approve(batchKey, "qa-1", "QUALITY", "CK-A", 422);
124	        assertEquals("QUARANTINED", currentStatus(batchKey));
125	    }
126	
127	    @Test
128	    void approvalConstraints_duplicateRole_sameActor_inspectorRejected() throws Exception {
129	        String batchKey = "BK-CONSTRAINT-" + unique();
130	        createBatch(batchKey, List.of("t1"), 201);
131	        submitTest(batchKey, testReq("TK-1", "t1", "PASS", "inspector-1"), null, null, 201);
132	
133	        // 检验人不能批准
134	        approve(batchKey, "inspector-1", "QUALITY", "CK-A0", 422);
135	        assertEquals("PENDING_RELEASE", currentStatus(batchKey));
136	
137	        approve(batchKey, "qa-1", "QUALITY", "CK-A1", 201);
138	        // 重复角色
139	        approve(batchKey, "ops-1", "QUALITY", "CK-A2", 409);
140	        // 同一人不能完成两种角色
141	        approve(batchKey, "qa-1", "OPERATIONS", "CK-A3", 409);
142	        assertEquals("RELEASE_REVIEW", currentStatus(batchKey));
143	
144	        approve(batchKey, "ops-1", "OPERATIONS", "CK-A4", 201);
145	        assertEquals("RELEASED", currentStatus(batchKey));
