154	        String batchKey = "BK-RC-EARLY-" + unique();
155	        createBatch(batchKey, List.of("t1"), 201);
156	        recall(batchKey, "u", "提前召回", "CK-R", 409);
157	        assertEquals("QUARANTINED", currentStatus(batchKey));
158	    }
