160	    // ---------- 400 / 404 ----------
161	
162	    @Test
163	    void invalidBodiesAndHeaders_return400() throws Exception {
164	        // 必做项为空
165	        String emptyTests = "{\"commandKey\":\"c\",\"batchKey\":\"b\",\"productCode\":\"p\","
166	                + "\"batchNo\":\"n\",\"producedAt\":\"2026-01-01T00:00:00Z\",\"requiredTests\":[]}";
167	        mockMvc.perform(post("/api/batches").contentType(MediaType.APPLICATION_JSON).content(emptyTests))
168	                .andExpect(status().isBadRequest());
