171	        String sixTests = "{\"commandKey\":\"c\",\"batchKey\":\"b2\",\"productCode\":\"p\","
172	                + "\"batchNo\":\"n\",\"producedAt\":\"2026-01-01T00:00:00Z\","
173	                + "\"requiredTests\":[\"a\",\"b\",\"c\",\"d\",\"e\",\"f\"]}";
174	        mockMvc.perform(post("/api/batches").contentType(MediaType.APPLICATION_JSON).content(sixTests))
175	                .andExpect(status().isBadRequest());
