178	        String duplicate = createBody("BK-DUP-ITEM-" + unique(), List.of("a", "a"));
179	        mockMvc.perform(post("/api/batches").contentType(MediaType.APPLICATION_JSON).content(duplicate))
180	                .andExpect(status().isBadRequest());
181	
182	        // result 枚举非法
183	        String badResult = "{\"commandKey\":\"c\",\"testKey\":\"t\",\"testItem\":\"a\","
184	                + "\"result\":\"MAYBE\",\"inspector\":\"i\"}";
185	        mockMvc.perform(post("/api/batches/BK-X/tests").contentType(MediaType.APPLICATION_JSON).content(badResult))
186	                .andExpect(status().isBadRequest());
