190	        mockMvc.perform(post("/api/batches/BK-X/approvals")
191	                        .contentType(MediaType.APPLICATION_JSON).content(approveBody))
192	                .andExpect(status().isBadRequest());
193	        mockMvc.perform(post("/api/batches/BK-X/approvals")
194	                        .header("X-Actor-Id", "qa").header("X-Approval-Role", "BOSS")
